// Verify shared secret and payload
const headers = $input.item.json.headers || {};
const secretHeader = headers['x-webhook-secret'] || headers['X-Webhook-Secret'];
const expectedSecret = $env.N8N_WEBHOOK_SECRET;

if (!secretHeader || secretHeader !== expectedSecret) {
  throw new Error('Unauthorized: Invalid or missing webhook shared secret.');
}

const body = $input.item.json.body || {};
if (!body.fileData || !body.fileName || !body.mimeType) {
  throw new Error('Bad Request: Missing required document payload fields (fileData, fileName, mimeType).');
}

return {
  fileData: body.fileData,
  fileName: body.fileName,
  mimeType: body.mimeType,
  idempotencyKey: body.idempotencyKey || null
};

