const response = $input.item.json;
const prev = $('Validate Request & Secret').first().json;

let rawText = '';
try {
  rawText = response.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('Gemini API returned an invalid or empty response structure.');
}

let data = {};
try {
  data = JSON.parse(rawText.trim());
} catch (e) {
  throw new Error('Failed to parse Gemini output as JSON: ' + rawText.slice(0, 100));
}

const issues = Array.isArray(data.validationIssues) ? [...data.validationIssues] : [];

// 1. Sanitize & Validate Vendor
let vendor = typeof data.vendor === 'string' && data.vendor.trim() ? data.vendor.trim().slice(0, 255) : null;
if (!vendor) {
  issues.push({ code: 'MISSING_VENDOR', message: 'Vendor name could not be identified', severity: 'warning', field: 'vendor' });
}

// 2. Invoice Number
let invoiceNumber = typeof data.invoiceNumber === 'string' && data.invoiceNumber.trim() ? data.invoiceNumber.trim().slice(0, 100) : null;
if (!invoiceNumber) {
  issues.push({ code: 'MISSING_INVOICE_NUMBER', message: 'Invoice number was not found', severity: 'warning', field: 'invoiceNumber' });
}

// 3. Description
let description = typeof data.description === 'string' && data.description.trim() ? data.description.trim().slice(0, 1000) : null;

// 4. Validate Date
let expenseDate = null;
if (typeof data.expenseDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(data.expenseDate.trim())) {
  expenseDate = data.expenseDate.trim();
} else {
  issues.push({ code: 'MISSING_OR_INVALID_DATE', message: 'Missing or invalid YYYY-MM-DD date', severity: 'warning', field: 'expenseDate' });
}

// 5. Amount & Bounds
let amount = null;
let parsedAmount = null;
if (data.amount !== null && data.amount !== undefined) {
  const cleanAmount = String(data.amount).replace(/[^0-9.-]/g, '');
  parsedAmount = parseFloat(cleanAmount);
  if (isNaN(parsedAmount) || parsedAmount < 0) {
    issues.push({ code: 'INVALID_AMOUNT', message: 'Amount is invalid or negative', severity: 'error', field: 'amount' });
  } else {
    amount = parsedAmount.toFixed(2);
  }
} else {
  issues.push({ code: 'MISSING_AMOUNT', message: 'Total amount was not found', severity: 'error', field: 'amount' });
}

// 6. Currency
let currency = null;
if (typeof data.currency === 'string' && data.currency.trim()) {
  const upperCurr = data.currency.trim().toUpperCase();
  currency = upperCurr.slice(0, 10);
  if (!/^[A-Z]{3}$/.test(currency)) {
    issues.push({ code: 'NON_STANDARD_CURRENCY', message: `Currency ${currency} is non-standard`, severity: 'warning', field: 'currency' });
  }
} else {
  issues.push({ code: 'MISSING_CURRENCY', message: 'Currency code was not found', severity: 'error', field: 'currency' });
}

// 7. Tax Amount
let taxAmount = null;
if (data.taxAmount !== null && data.taxAmount !== undefined) {
  const cleanTax = String(data.taxAmount).replace(/[^0-9.-]/g, '');
  const parsedTax = parseFloat(cleanTax);
  if (!isNaN(parsedTax) && parsedTax >= 0) {
    taxAmount = parsedTax.toFixed(2);
    if (parsedAmount !== null && parsedTax > parsedAmount) {
      issues.push({ code: 'TAX_EXCEEDS_TOTAL', message: 'Tax amount exceeds total amount', severity: 'error', field: 'taxAmount' });
    }
  }
}

// 8. Category
const validCategories = ['personnel', 'travel', 'equipment', 'software', 'events', 'operational', 'uncategorized'];
let category = 'uncategorized';
if (typeof data.category === 'string' && validCategories.includes(data.category.trim().toLowerCase())) {
  category = data.category.trim().toLowerCase();
} else {
  issues.push({ code: 'DEFAULT_CATEGORY', message: 'Category defaulted to uncategorized', severity: 'warning', field: 'category' });
}

// 9. Initial Status
let validationStatus = 'valid';
const hasErrors = issues.some(i => i.severity === 'error');
if (hasErrors || !vendor || !amount || !currency || issues.length > 0) {
  validationStatus = 'needs_review';
}

return {
  expenseDate,
  vendor,
  invoiceNumber,
  description,
  amount,
  currency,
  taxAmount,
  category,
  validationStatus,
  validationIssues: JSON.stringify(issues),
  sourceFileName: prev.fileName,
  idempotencyKey: prev.idempotencyKey
};

