=SELECT id, vendor, "invoiceNumber", amount, currency, "expenseDate"
FROM "Expense"
WHERE (
  "vendor" ILIKE {{ $json.vendor ? `'` + $json.vendor.replace(/'/g, "''") + `'` : 'NULL' }}
  AND (
    (
      "invoiceNumber" IS NOT NULL
      AND {{ $json.invoiceNumber ? `'` + $json.invoiceNumber.replace(/'/g, "''") + `'` : 'NULL' }} IS NOT NULL
      AND "invoiceNumber" ILIKE {{ $json.invoiceNumber ? `'` + $json.invoiceNumber.replace(/'/g, "''") + `'` : 'NULL' }}
      AND amount = {{ $json.amount || 0 }}
      AND currency ILIKE {{ $json.currency ? `'` + $json.currency.replace(/'/g, "''") + `'` : 'NULL' }}
    )
    OR
    (
      "invoiceNumber" IS NULL
      AND {{ $json.invoiceNumber ? 'FALSE' : 'TRUE' }}
      AND "expenseDate"::date = {{ $json.expenseDate ? `'` + $json.expenseDate + `'::date` : 'NULL' }}
      AND amount = {{ $json.amount || 0 }}
      AND currency ILIKE {{ $json.currency ? `'` + $json.currency.replace(/'/g, "''") + `'` : 'NULL' }}
    )
  )
)
LIMIT 1;

