const duplicateCheck = $input.item.json;
const extracted = $('Validate & Sanitize Extraction').first().json;

const issues = JSON.parse(extracted.validationIssues || '[]');
let status = extracted.validationStatus;

// If query returned a row, it's a duplicate candidate
if (duplicateCheck && duplicateCheck.id) {
  status = 'duplicate_suspected';
  issues.push({
    code: 'DUPLICATE_CANDIDATE',
    message: `Suspected duplicate of existing expense record ID ${duplicateCheck.id}`,
    severity: 'warning'
  });
}

// Generate standard CUID-like or UUID identifier for Postgres insert
const generatedId = 'exp_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);

return {
  id: generatedId,
  expenseDate: extracted.expenseDate,
  vendor: extracted.vendor,
  invoiceNumber: extracted.invoiceNumber,
  description: extracted.description,
  amount: extracted.amount,
  currency: extracted.currency,
  taxAmount: extracted.taxAmount,
  category: extracted.category,
  validationStatus: status,
  validationIssues: JSON.stringify(issues),
  sourceFileName: extracted.sourceFileName
};
